import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Construct true-cost regret schedules and improve them by exact repair."""
    import time

    now = time.perf_counter()
    global _schedule_search_deadline
    if "_schedule_search_deadline" not in globals():
        _schedule_search_deadline = now + 330.0
    deadline = min(_schedule_search_deadline, now + 105.0)

    n = workload.num_txns
    if n == 0:
        return 0, []

    cache = {}

    def cost(seq):
        key = tuple(seq)
        if key not in cache:
            cache[key] = workload.get_opt_seq_cost(list(key))
        return cache[key]

    identity = list(range(n))
    best_seq = identity[:]
    best_cost = cost(best_seq)

    # Preserve enough time for complete, global insertion construction before
    # applying more expensive destruction/repair moves.
    construct_deadline = min(deadline, now + 48.0)

    def construct(reverse=False):
        """Seed a weighted precedence tournament, then polish by exact insertion."""
        pair_cost = {}
        weight = {}

        # Every pair contributes a preference based on the simulator's true
        # partial-order cost.  The difference is the strength of that preference.
        for i in range(n):
            for j in range(i + 1, n):
                if time.perf_counter() >= construct_deadline:
                    break
                cij = cost([i, j])
                cji = cost([j, i])
                pair_cost[i, j] = cij
                pair_cost[j, i] = cji
                if cij <= cji:
                    weight[i, j] = cji - cij
                    weight[j, i] = 0
                else:
                    weight[j, i] = cij - cji
                    weight[i, j] = 0

        # Weighted insertion minimizes backward precedence pressure against the
        # transactions already placed, while remaining a complete permutation.
        order = []
        remaining = set(range(n))
        while remaining:
            txn = min(
                remaining,
                key=lambda x: (
                    -sum(weight.get((x, y), 0) for y in remaining if y != x)
                    + sum(weight.get((y, x), 0) for y in remaining if y != x),
                    x,
                ),
            )
            best_pos = 0
            best_pressure = None
            for pos in range(len(order) + 1):
                pressure = 0
                for k, other in enumerate(order):
                    if k < pos:
                        pressure += weight.get((other, txn), 0)
                    else:
                        pressure += weight.get((txn, other), 0)
                value = (pressure, pos)
                if best_pressure is None or value < best_pressure:
                    best_pressure = value
                    best_pos = pos
            order.insert(best_pos, txn)
            remaining.remove(txn)

        # One exact relocate pass converts the structural seed into a schedule
        # evaluated using the real makespan rather than only pair preferences.
        for txn in order[:]:
            if time.perf_counter() >= construct_deadline:
                break
            partial = [x for x in order if x != txn]
            choice = None
            for pos in range(len(partial) + 1):
                trial = partial[:pos] + [txn] + partial[pos:]
                candidate = (cost(trial), pos)
                if choice is None or candidate < choice[0]:
                    choice = (candidate, trial)
            if choice is not None:
                order = choice[1]
        return order

    if time.perf_counter() < construct_deadline:
        candidate = construct()
        candidate_cost = cost(candidate)
        if candidate_cost < best_cost:
            best_seq, best_cost = candidate, candidate_cost

    ruin_count = min(8, max(3, n // 8), n)

    for attempt in range(4):
        if time.perf_counter() >= deadline:
            break

        impacts = []
        for txn in best_seq:
            if time.perf_counter() >= deadline:
                break
            remainder = [x for x in best_seq if x != txn]
            impacts.append((best_cost - cost(remainder), txn))

        if len(impacts) != n:
            break

        impacts.sort(
            key=lambda item: (-item[0], (item[1] - attempt) % max(1, n))
        )
        removed = {txn for _, txn in impacts[:ruin_count]}
        partial = [txn for txn in best_seq if txn not in removed]

        while removed and time.perf_counter() < deadline:
            choice = None
            for txn in sorted(
                removed, key=lambda x: (x - attempt) % max(1, n)
            ):
                for pos in range(len(partial) + 1):
                    trial = partial[:pos] + [txn] + partial[pos:]
                    candidate = (cost(trial), txn, pos, trial)
                    if choice is None or candidate[:3] < choice[:3]:
                        choice = candidate

            if choice is None:
                break
            _, txn, _, partial = choice
            removed.remove(txn)

        partial.extend(sorted(removed))
        candidate = partial
        candidate_cost = cost(candidate)

        improved = True
        while improved and time.perf_counter() < deadline:
            improved = False
            for pos in range(n - 1):
                if time.perf_counter() >= deadline:
                    break
                trial = candidate[:]
                trial[pos], trial[pos + 1] = trial[pos + 1], trial[pos]
                value = cost(trial)
                if value < candidate_cost:
                    candidate, candidate_cost = trial, value
                    improved = True
                    break

        if candidate_cost < best_cost:
            best_seq, best_cost = candidate[:], candidate_cost

    if len(best_seq) != n or set(best_seq) != set(range(n)):
        best_seq = identity
        best_cost = cost(identity)

    return best_cost, best_seq

# EVOLVE-BLOCK-END


def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
